using System.Data; using MediDesk.Business.Interfaces; using MediDesk.Common.Contracts.Catalog; using MediDesk.Common.Contracts.Finance; using Microsoft.Data.SqlClient; namespace MediDesk.Data.Repositories; public sealed class SchemeRepository(SqlConnectionFactory f):ISchemeRepository {const string C="Id,Name,AppliesTo,SchemeType,Value,ValidFrom,ValidUntil,IsActive,RowVersion"; public async Task<PagedResponse<SchemeDto>> GetPageAsync(SchemeQuery q,CancellationToken ct){var w="IsDeleted=0 AND (@S IS NULL OR Name LIKE @L OR AppliesTo LIKE @L)";await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand($"SELECT COUNT(1) FROM dbo.Schemes WHERE {w};SELECT {C} FROM dbo.Schemes WHERE {w} ORDER BY Name OFFSET @O ROWS FETCH NEXT @P ROWS ONLY",c);cmd.Parameters.Add("@S",SqlDbType.NVarChar,160).Value=(object?)q.Search??DBNull.Value;cmd.Parameters.Add("@L",SqlDbType.NVarChar,170).Value=q.Search is null?DBNull.Value:$"%{q.Search}%";cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var rd=await cmd.ExecuteReaderAsync(ct);await rd.ReadAsync(ct);var total=rd.GetInt32(0);await rd.NextResultAsync(ct);var a=new List<SchemeDto>();while(await rd.ReadAsync(ct))a.Add(Read(rd));return new(a,q.Page,q.PageSize,total);} public async Task<SchemeDto>CreateAsync(CreateSchemeRequest x,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("INSERT dbo.Schemes(Name,AppliesTo,SchemeType,Value,ValidFrom,ValidUntil,CreatedByUserId) OUTPUT INSERTED.Id VALUES(@N,@A,@T,@V,@F,@U,@User)",c);Add(cmd,x);cmd.Parameters.Add("@User",SqlDbType.BigInt).Value=u;var id=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));return (await GetPageAsync(new SchemeQuery(PageSize:200),ct)).Items.First(x=>x.Id==id);} public async Task<SchemeWriteResult>UpdateAsync(long id,UpdateSchemeRequest x,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("UPDATE dbo.Schemes SET Name=@N,AppliesTo=@A,SchemeType=@T,Value=@V,ValidFrom=@F,ValidUntil=@U,IsActive=@Active,UpdatedByUserId=@User,UpdatedAtUtc=SYSUTCDATETIME() WHERE Id=@Id AND IsDeleted=0 AND RowVersion=@Row",c);Add(cmd,x);cmd.Parameters.Add("@Active",SqlDbType.Bit).Value=x.IsActive;cmd.Parameters.Add("@User",SqlDbType.BigInt).Value=u;cmd.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;cmd.Parameters.Add("@Row",SqlDbType.Timestamp).Value=Convert.FromBase64String(x.RowVersion);return await cmd.ExecuteNonQueryAsync(ct)>0?new(true):new(false,NotFound:true);} public async Task<bool>SoftDeleteAsync(long id,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("UPDATE dbo.Schemes SET IsDeleted=1,UpdatedByUserId=@U,UpdatedAtUtc=SYSUTCDATETIME() WHERE Id=@Id AND IsDeleted=0",c);cmd.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;cmd.Parameters.Add("@U",SqlDbType.BigInt).Value=u;return await cmd.ExecuteNonQueryAsync(ct)>0;}static void Add(SqlCommand c,CreateSchemeRequest x){c.Parameters.Add("@N",SqlDbType.NVarChar,160).Value=x.Name;c.Parameters.Add("@A",SqlDbType.NVarChar,80).Value=x.AppliesTo;c.Parameters.Add("@T",SqlDbType.NVarChar,30).Value=x.SchemeType;c.Parameters.Add("@V",SqlDbType.Decimal).Value=x.Value;c.Parameters.Add("@F",SqlDbType.Date).Value=x.ValidFrom;c.Parameters.Add("@U",SqlDbType.Date).Value=x.ValidUntil;}static void Add(SqlCommand c,UpdateSchemeRequest x){Add(c,new CreateSchemeRequest(x.Name,x.AppliesTo,x.SchemeType,x.Value,x.ValidFrom,x.ValidUntil));}static SchemeDto Read(SqlDataReader r)=>new(r.GetInt64(0),$"SCH-{r.GetInt64(0):0000}",r.GetString(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),DateOnly.FromDateTime(r.GetDateTime(5)),DateOnly.FromDateTime(r.GetDateTime(6)),r.GetBoolean(7),Convert.ToBase64String((byte[])r[8]));}

